INSERT INTO creative_templates (category, name, objective, headline, primary_text, description, call_to_action, placeholders) VALUES
('new_launch', 'New model launch', 'new_vehicle_launch', 'The new {model} is here', 'Be among the first in {city} to see the new {brand} {model}. Visit {dealership} to explore it up close.', 'Visit {dealership}', 'LEARN_MORE', ARRAY['brand','model','city','dealership']),
('test_drive', 'Book a test drive', 'test_drive_enquiries', 'Test drive the {model}', 'Experience the {brand} {model} on roads you know. Book a test drive at {dealership}, {city}.', 'Book your slot', 'BOOK_NOW', ARRAY['brand','model','city','dealership']),
('exchange', 'Exchange your vehicle', 'exchange_offer', 'Upgrade to the {model}', 'Thinking of upgrading? Get your current vehicle evaluated at {dealership} and explore the {brand} {model}. Offer terms apply.', 'Get an evaluation', 'GET_QUOTE', ARRAY['brand','model','dealership']),
('festive', 'Festive season', 'new_car_promotion', 'Celebrate with a new {brand}', 'Make this festive season special with the {brand} {model}. Visit {dealership} in {city} for current offers. Terms apply.', 'See festive offers', 'GET_OFFER', ARRAY['brand','model','city','dealership']),
('pre_owned', 'Pre-owned stock', 'pre_owned_enquiries', 'Certified pre-owned cars in {city}', 'Browse inspected pre-owned vehicles at {dealership}. Visit us or enquire online to check availability.', 'Check availability', 'CONTACT_US', ARRAY['city','dealership']),
('service_camp', 'Service camp', 'service_camp', '{brand} service camp at {dealership}', 'Bring your {brand} for a check-up at our service camp. Book a slot at {dealership}, {location}.', 'Book a service slot', 'BOOK_NOW', ARRAY['brand','dealership','location']),
('accessories', 'Genuine accessories', 'accessories', 'Genuine accessories for your {model}', 'Personalise your {brand} {model} with accessories fitted by trained technicians at {dealership}.', 'Explore accessories', 'LEARN_MORE', ARRAY['brand','model','dealership']),
('ev', 'EV test drive', 'ev_promotion', 'Drive electric with the {model}', 'Discover the {brand} {model} at {dealership}, {city}. Ask our team about charging and ownership.', 'Book an EV test drive', 'BOOK_NOW', ARRAY['brand','model','city','dealership']),
('event', 'Dealership event', 'dealership_event', 'You are invited to {dealership}', 'Join us at {dealership}, {location} for our showroom event. See the latest models and meet our team.', 'Plan your visit', 'LEARN_MORE', ARRAY['dealership','location']);
